"use client";

// Ported from susegad-ui's <sg-tile-band> custom element (packages/components/tile-band/tile-band.js)
// to a React component, per the project's port instructions. Original copyright (c) 2026
// Sarat Chandra Gnanamgari, Asymmetrica — MIT licensed. Original comment, preserved:
//
// A band of hand-painted tiles for a border or a divider: Goan azulejo, the blue-and-white
// tiles of the Portuguese-era houses and churches, and its majolica cousin (cobalt, lemon and leaf green).
// Four motifs (a rosette, a quatrefoil, quarter-circle corners, a vine), geometric and floral only, laid from
// a seed. Painted once on a canvas and kept; there is no frame loop. It runs along the page or down it.
//
//   <TileBand />                                   a decoration: aria-hidden
//   <TileBand><hr /></TileBand>                     a divider: the <hr> is the separator, and is the cobalt line without JavaScript
//   <TileBand tones="majolica" seed="church" />
//   <TileBand orientation="vertical" style={{ height: '20rem' }} />
//
// Props: tones (azulejo | majolica, default azulejo), seed, orientation (horizontal | vertical, default
// horizontal), register (quiet | warm | playful, default warm). Size: --sg-tile-size (default 4rem, 3.25rem
// on a phone) is the tile you would like; the band fits whole square tiles to its length and sets its own
// thickness to match.

import * as React from "react";
import { mountBand, type BandSkin } from "@/components/ui/tile-band-utils/band";

export type TileBandTones = "azulejo" | "majolica";
export type TileBandOrientation = "horizontal" | "vertical";
export type TileBandRegister = "quiet" | "warm" | "playful";

export interface TileBandProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  /** azulejo (blue-and-white) or majolica (cobalt, lemon, leaf). Default azulejo. */
  tones?: TileBandTones;
  /** Lays the band deterministically: the same seed paints the same tiles every time. */
  seed?: string;
  /** horizontal (a border) or vertical (an edge down the page). Default horizontal. */
  orientation?: TileBandOrientation;
  /** quiet: flat line-art, still. warm: hand-painted glaze, still. playful: the glaze, and a tile turns on touch. Default warm. */
  register?: TileBandRegister;
  /** Put an <hr /> here to make the band a real divider; omit it and the band is pure decoration (aria-hidden). */
  children?: React.ReactNode;
}

const LOOKS: Record<
  TileBandRegister,
  { look: "line" | "glaze"; turns: boolean }
> = {
  quiet: { look: "line", turns: false },
  warm: { look: "glaze", turns: false },
  playful: { look: "glaze", turns: true },
};

/** Component motion: 'still' under reduced motion, 'state' in quiet, then 'ambient' or 'full'. */
function resolveMotion(register: TileBandRegister, reducedMotion: boolean) {
  if (reducedMotion) return "still";
  if (register === "quiet") return "state";
  return register === "playful" ? "full" : "ambient";
}

export default function TileBand({
  tones = "azulejo",
  seed = "azulejo",
  orientation = "horizontal",
  register = "warm",
  children,
  className,
  style,
  ...rest
}: TileBandProps) {
  const hostRef = React.useRef<HTMLDivElement | null>(null);
  const skinRef = React.useRef<BandSkin | null>(null);
  const visibleRef = React.useRef(true);
  const [reducedMotion, setReducedMotion] = React.useState(false);

  const vertical = orientation === "vertical";
  // The native child: an <hr> makes the band a real divider; without one it is only decoration.
  const hasNative = React.Children.count(children) > 0;

  React.useEffect(() => {
    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    const onChange = () => setReducedMotion(!!mq?.matches);
    onChange();
    mq?.addEventListener?.("change", onChange);
    return () => mq?.removeEventListener?.("change", onChange);
  }, []);

  React.useEffect(() => {
    const host = hostRef.current;
    if (!host || typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver(([entry]) => {
      visibleRef.current = entry.isIntersecting;
      skinRef.current?.update({
        seed,
        tones,
        vertical,
        visible: visibleRef.current,
      });
    });
    io.observe(host);
    return () => io.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seed, tones, vertical]);

  // Mount (or remount) the skin whenever the register or the resolved motion changes — the same
  // trigger the original component used to reload a skin (component.js's #load()).
  React.useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const { look, turns } = LOOKS[register];
    const motion = resolveMotion(register, reducedMotion);
    const ctx = {
      get motion() {
        return motion;
      },
      get visible() {
        return visibleRef.current;
      },
    };
    const skin = mountBand(host, ctx, { look, turns });
    skinRef.current = skin;
    host.dataset.skin = register;
    skin.update({ seed, tones, vertical, visible: visibleRef.current });
    return () => {
      skin.destroy();
      delete host.dataset.skin;
      skinRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [register, reducedMotion]);

  // Repaint when the public, visual-affecting props change.
  React.useEffect(() => {
    skinRef.current?.update({
      seed,
      tones,
      vertical,
      visible: visibleRef.current,
    });
  }, [seed, tones, vertical]);

  return (
    <div
      ref={hostRef}
      data-orientation={vertical ? "vertical" : undefined}
      aria-hidden={hasNative ? undefined : "true"}
      className={["sg-tile-band", className].filter(Boolean).join(" ")}
      style={style}
      {...rest}
    >
      {children}
    </div>
  );
}

