import TileBand from "@/components/ui/tile-band";

export default function TileBandVerticalDemo() {
  return (
    <div className="w-full max-w-2xl mx-auto p-10 bg-[#FBF8EE] grid grid-cols-[auto_1fr] gap-6 items-stretch">
      <TileBand
        orientation="vertical"
        register="warm"
        tones="majolica"
        seed="edge"
        style={{ minHeight: "15rem" }}
      />
      <div className="self-center max-w-sm">
        <h3 className="text-lg font-medium text-[#2a241b] mb-2">
          Down the side of a page
        </h3>
        <p className="text-sm text-[#6b5a3e]">
          The same band runs down the page as an edge: it turns every motif a
          quarter so the vines climb, and fits whole tiles to the height.
        </p>
      </div>
    </div>
  );
}
